insert into kafaa_courses (id, programme_id, code, title_en, title_ar, modality, initial, mandatory, audience, competency_ids, objectives, prerequisites, duration_hours, qualifying, evaluation_form_id, owner_role, public_summary, summary_en, summary_ar, sources, packaging, pass_mark, validity_months, nexus_course_id, concept_content) values
('c-et-ghg-mgr', 'cld', 'ET-GR-101', 'GHG and ESG basics for managers', 'أساسيات غازات الدفيئة والحوكمة البيئية والاجتماعية للمديرين', 'elearning', false, false, 'staff', '{}'::text[], '[{"en":"Explain emission scopes, an emissions inventory and the difference between reductions and avoided emissions","ar":"شرح نطاقات الانبعاثات وجرد الانبعاثات والفرق بين التخفيض والانبعاثات التي تم تجنبها"},{"en":"Read a sustainability disclosure and find its main metrics, scope and date","ar":"قراءة إفصاح عن الاستدامة وتحديد مقاييسه الرئيسية ونطاقه وتاريخه"},{"en":"Describe the human capital reporting areas and the baseline metrics of ISO 30414:2025","ar":"وصف مجالات تقارير رأس المال البشري والمقاييس الأساسية في المعيار ISO 30414:2025"}]'::jsonb, '{}'::text[], 3, false, null, 'Corporate Sustainability', false, 'Three short modules for line managers: greenhouse-gas accounting basics, reading a sustainability disclosure, and human capital reporting concepts. Concept content; no figures about ENEC.', 'ثلاث وحدات قصيرة للمديرين المباشرين: أساسيات محاسبة غازات الدفيئة، وقراءة إفصاح عن الاستدامة، ومفاهيم تقارير رأس المال البشري. محتوى مفاهيمي، ولا أرقام عن المؤسسة.', '[{"id":"fs43-iso30414","label":"ISO TC 260 · ISO 30414:2025, strengthening human capital reporting (24 Aug 2025)","url":"https://committee.iso.org/sites/tc260/home/news/content-left-area/news-and-updates/iso-30414-2025-strengthening-hum.html","as_of":"2026-10-10"},{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'xapi', null, null, null, true),
('c-et-esg-clinic', 'cld', 'ET-GR-102', 'ESG data clinic: your team''s numbers', 'عيادة بيانات الحوكمة البيئية والاجتماعية: أرقام فريقك', 'clinic', false, false, 'staff', '{}'::text[], '[{"en":"Trace one of your team''s resource or emissions figures back to its source and scope","ar":"تتبّع أحد أرقام الموارد أو الانبعاثات لفريقك إلى مصدره ونطاقه"},{"en":"Draft a short qualitative explanation for a change in a metric, as ISO 30414:2025 asks","ar":"صياغة شرح نوعي قصير لتغيّر في أحد المقاييس، كما يطلب المعيار ISO 30414:2025"}]'::jsonb, array['c-et-ghg-mgr']::text[], 2, false, null, 'Corporate Sustainability', false, 'A two-hour facilitated clinic: managers bring one team metric, check its source and scope, and write the narrative that should accompany it.', 'عيادة بإشراف ميسّر لمدة ساعتين: يحضر المديرون مقياساً واحداً لفريقهم، ويتحققون من مصدره ونطاقه، ويكتبون الشرح الذي ينبغي أن يرافقه.', '[{"id":"fs43-iso30414","label":"ISO TC 260 · ISO 30414:2025, strengthening human capital reporting (24 Aug 2025)","url":"https://committee.iso.org/sites/tc260/home/news/content-left-area/news-and-updates/iso-30414-2025-strengthening-hum.html","as_of":"2026-10-10"},{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"}]'::jsonb, 'xapi', null, null, null, true)
insert into kafaa_credit_tags (id, item_kind, item_id, title_en, title_ar, nqf_level, notional_hours, credits, indicative, basis_en, basis_ar, stack_ids, status, listed, source_url, as_of, version, updated_by, updated_at) values
('ct:course:c-et-esg-clinic', 'course', 'c-et-esg-clinic', 'ESG data clinic: your team''s numbers', 'عيادة بيانات الحوكمة البيئية والاجتماعية: أرقام فريقك', 3, 3, 0.3, true, '2 contact hours x 1.5 for study and practice; level from the course''s skill objectives (Kafa''a level 1).', '2 ساعة تواصل × 1.5 للدراسة والممارسة؛ المستوى مأخوذ من أهداف المهارات في الدورة (مستوى كفاءة 1).', '{}'::text[], 'published', true, 'https://uaelegislation.gov.ae/en/legislations/2615/download', '2026-10-10', 1, 'p-training-mgr', '2026-10-10T09:00:00Z'),
('ct:course:c-et-ghg-mgr', 'course', 'c-et-ghg-mgr', 'GHG and ESG basics for managers', 'أساسيات غازات الدفيئة والحوكمة البيئية والاجتماعية للمديرين', 3, 6, 0.6, true, '3 contact hours x 2 for study and practice; level from the course''s skill objectives (Kafa''a level 1).', '3 ساعة تواصل × 2 للدراسة والممارسة؛ المستوى مأخوذ من أهداف المهارات في الدورة (مستوى كفاءة 1).', '{}'::text[], 'published', true, 'https://uaelegislation.gov.ae/en/legislations/2615/download', '2026-10-10', 1, 'p-training-mgr', '2026-10-10T09:00:00Z'),
('ct:pathway:pw-et-esg-managers', 'pathway', 'pw-et-esg-managers', 'ESG and GHG literacy for managers', 'الإلمام بالحوكمة البيئية والاجتماعية وغازات الدفيئة للمديرين', 3, 5, 0.5, true, 'Practice and project component only (40% of 3 months at 1 h a week); the pathway''s courses count separately.', 'مكوّن الممارسة والمشروع فقط (40% من 3 أشهر بمعدل 1 ساعة أسبوعياً)؛ تُحتسب دورات المسار بشكل منفصل.', array['st-clean-energy']::text[], 'published', true, 'https://uaelegislation.gov.ae/en/legislations/2615/download', '2026-10-10', 1, 'p-training-mgr', '2026-10-10T09:00:00Z'),
('ct:pathway:pw-et-system-integration', 'pathway', 'pw-et-system-integration', 'Energy-system integration: from awareness to practitioner', 'تكامل منظومة الطاقة: من الوعي إلى الممارسة', 4, 19, 1.9, true, 'Practice and project component only (40% of 6 months at 2 h a week); the pathway''s courses count separately.', 'مكوّن الممارسة والمشروع فقط (40% من 6 أشهر بمعدل 2 ساعة أسبوعياً)؛ تُحتسب دورات المسار بشكل منفصل.', array['st-clean-energy']::text[], 'published', true, 'https://uaelegislation.gov.ae/en/legislations/2615/download', '2026-10-10', 1, 'p-training-mgr', '2026-10-10T09:00:00Z')
insert into kafaa_external_resources (id, title_en, title_ar, provider_en, provider_ar, provider_url, url, format, hours, duration_en, duration_ar, cost_band, languages, skills, has_assessment, summary_en, summary_ar, criteria, criteria_note_en, criteria_note_ar, as_of, sources, status, listed, version, published_by, published_on, retired_reason, retired_on, created_by, updated_by, updated_at, sort) values
('xr-et-nea-plan2035', 'OECD-NEA Plan 2035: Scaling Technology, Growing Careers, Securing the Future', 'خطة وكالة الطاقة النووية 2035: توسيع التقنية، وتنمية المسارات المهنية، وتأمين المستقبل', 'OECD Nuclear Energy Agency', 'وكالة الطاقة النووية التابعة لمنظمة التعاون الاقتصادي والتنمية', 'https://www.oecd-nea.org', 'https://www.oecd-nea.org/upload/docs/application/pdf/2025-10/plan_2035_-_vision_paper_-_final_version.pdf', 'reading', null, 'Vision paper (PDF); a short read', 'ورقة رؤية (PDF)؛ قراءة قصيرة', 'free', array['en']::text[], '[{"skill_id":"sk-fs-gr-grid","level":1}]'::jsonb, false, 'The NEA workforce initiative launched in April 2024 in support of tripling nuclear capacity by 2050, with three pathways: inspire, mentor and network.', 'مبادرة القوى العاملة لوكالة الطاقة النووية التي أُطلقت في أبريل 2024 دعماً لمضاعفة القدرة النووية ثلاث مرات بحلول 2050، عبر ثلاثة مسارات: الإلهام والإرشاد والتواصل.', '{"relevance":2,"standing":3,"assessment":0,"language":2}'::jsonb, '', '', '2026-10-10', '[{"id":"fs42-nea-plan2035","label":"OECD-NEA · Plan 2035 vision paper: Scaling Technology, Growing Careers, Securing the Future (Oct 2025)","url":"https://www.oecd-nea.org/upload/docs/application/pdf/2025-10/plan_2035_-_vision_paper_-_final_version.pdf","accessed":"2026-10-10"}]'::jsonb, 'published', true, 1, 'p-training-mgr', '2026-10-11', null, null, 'p-training-mgr', 'p-training-mgr', '2026-10-11T08:00:00Z', 12),
('xr-et-iea-wee2025', 'IEA World Energy Employment 2025: what it says about skills', 'تقرير الوكالة الدولية للطاقة عن التوظيف في قطاع الطاقة 2025: ما يقوله عن المهارات', 'NucNet (report on the IEA World Energy Employment 2025)', 'نوك نت (تقرير عن التوظيف في قطاع الطاقة 2025 للوكالة الدولية للطاقة)', 'https://smr.nucnet.org', 'https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025', 'reading', null, 'News article; a short read', 'مقال إخباري؛ قراءة قصيرة', 'free', array['en']::text[], '[{"skill_id":"sk-fs-gr-grid","level":1}]'::jsonb, false, 'The first edition with occupation-level estimates: energy employment, labour shortages in technical trades and nuclear specialists, and the graduate pipeline needed by 2030.', 'أول إصدار بتقديرات على مستوى المهن: التوظيف في قطاع الطاقة، ونقص العمالة في المهن الفنية والمتخصصين النوويين، وأعداد الخريجين المطلوبة بحلول 2030.', '{"relevance":2,"standing":2,"assessment":0,"language":2}'::jsonb, '', '', '2026-10-10', '[{"id":"fs42-iea-wee","label":"NucNet · IEA World Energy Employment 2025: jobs growth in nuclear (Dec 2025)","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025","accessed":"2026-10-10"}]'::jsonb, 'published', true, 1, 'p-training-mgr', '2026-10-11', null, null, 'p-training-mgr', 'p-training-mgr', '2026-10-11T08:00:00Z', 13),
('xr-et-irena-jobs2025', 'Renewable Energy and Jobs: Annual Review 2025', 'الطاقة المتجددة والوظائف: المراجعة السنوية 2025', 'IRENA and the ILO (via EU BUILD UP)', 'الوكالة الدولية للطاقة المتجددة ومنظمة العمل الدولية (عبر منصة BUILD UP الأوروبية)', 'https://build-up.ec.europa.eu', 'https://build-up.ec.europa.eu/en/resources-and-tools/publications/annual-review-2025-renewable-energy-and-jobs', 'reading', null, 'Publication page; a short read', 'صفحة إصدار؛ قراءة قصيرة', 'free', array['en']::text[], '[{"skill_id":"sk-fs-gr-grid","level":1}]'::jsonb, false, 'The twelfth edition on renewable-energy employment, with 2024 data, slowing job growth and the call for training in digital skills and manufacturing.', 'الإصدار الثاني عشر عن التوظيف في الطاقة المتجددة، ببيانات 2024، وتباطؤ نمو الوظائف، والدعوة إلى التدريب على المهارات الرقمية والتصنيع.', '{"relevance":2,"standing":3,"assessment":0,"language":2}'::jsonb, '', '', '2026-10-10', '[{"id":"fs42-irena-jobs","label":"EU BUILD UP · IRENA and ILO, Renewable Energy and Jobs: Annual Review 2025","url":"https://build-up.ec.europa.eu/en/resources-and-tools/publications/annual-review-2025-renewable-energy-and-jobs","accessed":"2026-10-10"}]'::jsonb, 'published', true, 1, 'p-training-mgr', '2026-10-11', null, null, 'p-training-mgr', 'p-training-mgr', '2026-10-11T08:00:00Z', 14),
('xr-et-iso30414', 'ISO 30414:2025 human capital reporting: what changed', 'المعيار ISO 30414:2025 لإعداد تقارير رأس المال البشري: ما الذي تغيّر', 'ISO Technical Committee 260 (Human resource management)', 'اللجنة الفنية 260 في المنظمة الدولية للتوحيد القياسي (إدارة الموارد البشرية)', 'https://committee.iso.org', 'https://committee.iso.org/sites/tc260/home/news/content-left-area/news-and-updates/iso-30414-2025-strengthening-hum.html', 'reading', null, 'Committee news item; a short read', 'خبر من اللجنة؛ قراءة قصيرة', 'free', array['en']::text[], '[{"skill_id":"sk-fs-gr-esg","level":1}]'::jsonb, false, 'The second edition (24 August 2025) keeps 11 human capital areas, adds a baseline of 14 required metrics and asks for quantitative and qualitative disclosure with variance explanations.', 'يحتفظ الإصدار الثاني (24 أغسطس 2025) بأحد عشر مجالاً لرأس المال البشري، ويضيف مجموعة أساسية من 14 مقياساً إلزامياً، ويطلب إفصاحاً كمياً ونوعياً مع شرح الفروق.', '{"relevance":2,"standing":2,"assessment":0,"language":2}'::jsonb, '', '', '2026-10-10', '[{"id":"fs43-iso30414","label":"ISO TC 260 · ISO 30414:2025, strengthening human capital reporting (24 Aug 2025)","url":"https://committee.iso.org/sites/tc260/home/news/content-left-area/news-and-updates/iso-30414-2025-strengthening-hum.html","accessed":"2026-10-10"}]'::jsonb, 'published', true, 1, 'p-training-mgr', '2026-10-11', null, null, 'p-training-mgr', 'p-training-mgr', '2026-10-11T08:00:00Z', 15),
('xr-et-greencomp', 'GreenComp: the European sustainability competence framework', 'إطار "غرين كومب": الإطار الأوروبي لكفاءات الاستدامة', 'European Commission Joint Research Centre', 'مركز البحوث المشترك التابع للمفوضية الأوروبية', 'https://joint-research-centre.ec.europa.eu', 'https://joint-research-centre.ec.europa.eu/greencomp', 'reading', null, 'Framework page and PDF; a short read', 'صفحة الإطار وملف PDF؛ قراءة قصيرة', 'free', array['en']::text[], '[{"skill_id":"sk-fs-tr-environment","level":1},{"skill_id":"sk-fs-gr-esg","level":1}]'::jsonb, false, 'Twelve sustainability competences in four areas, built with the JRC method used for DigComp; a reference for designing learning, not a curriculum.', 'اثنتا عشرة كفاءة للاستدامة في أربعة مجالات، بُنيت بمنهجية مركز البحوث المشترك المستخدمة في DigComp؛ مرجع لتصميم التعلّم وليس منهجاً دراسياً.', '{"relevance":2,"standing":3,"assessment":0,"language":2}'::jsonb, '', '', '2026-10-10', '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","accessed":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","accessed":"2026-10-10"}]'::jsonb, 'published', true, 1, 'p-training-mgr', '2026-10-11', null, null, 'p-training-mgr', 'p-training-mgr', '2026-10-11T08:00:00Z', 16)
insert into kafaa_fl_cohorts (id, code, year, status, seats, starts_on, ends_on, title_en, title_ar, modules, brief_en, brief_ar, mentor_en, mentor_ar, sort) values
('flc-2025', 'FL-2025', 2025, 'completed', 8, '2024-10-01', '2025-06-30', 'Future Leaders pilot cohort 2025', 'الدفعة التجريبية لقادة المستقبل 2025', '[{"id":"flm-safety","title_en":"Leading safety culture","title_ar":"قيادة ثقافة السلامة","format_en":"Three days with a site visit","format_ar":"ثلاثة أيام مع زيارة ميدانية","weeks":6,"competency_ids":["fl-safety-leadership"]},{"id":"flm-regulation","title_en":"Regulation, licensing and international standards","title_ar":"التنظيم والترخيص والمعايير الدولية","format_en":"Three days with the licensing team","format_ar":"ثلاثة أيام مع فريق الترخيص","weeks":6,"competency_ids":["fl-regulatory"]},{"id":"flm-project","title_en":"Project, cost and outage economics","title_ar":"المشاريع والتكاليف واقتصاديات الانقطاعات","format_en":"Three days with a case study","format_ar":"ثلاثة أيام مع دراسة حالة","weeks":6,"competency_ids":["fl-project-cost"]},{"id":"flm-stakeholder","title_en":"Stakeholders, public communication and international affairs","title_ar":"أصحاب المصلحة والتواصل العام والشؤون الدولية","format_en":"Three days with a media exercise","format_ar":"ثلاثة أيام مع تمرين إعلامي","weeks":6,"competency_ids":["fl-stakeholder"]},{"id":"flm-knowledge","title_en":"Knowledge management and succession","title_ar":"إدارة المعرفة والتعاقب","format_en":"Three days with a capture interview","format_ar":"ثلاثة أيام مع مقابلة توثيق","weeks":6,"competency_ids":["fl-knowledge"]},{"id":"flm-future","title_en":"Leading the future plant: digital change, AI-augmented teams and new reactors","title_ar":"قيادة محطة المستقبل: التحول الرقمي والفرق المعززة بالذكاء الاصطناعي والمفاعلات الجديدة","format_en":"Three days with a governed AI drill and the 360 (form 2)","format_ar":"ثلاثة أيام مع تمرين ذكاء اصطناعي منضبط وتقييم 360 (النموذج 2)","weeks":6,"competency_ids":["fl-safety-leadership","fl-regulatory"]}]'::jsonb, 'Each participant writes a short policy paper on a question an executive sponsors (for example, how a future fleet would change workforce planning). Concept work: no deployment decision implied.', 'يكتب كل مشارك ورقة سياسات قصيرة حول سؤال يرعاه أحد التنفيذيين (مثل كيف سيغيّر أسطول مستقبلي تخطيط القوى العاملة). عمل مفاهيمي: لا يُفهم منه أي قرار نشر.', 'Each participant has a senior leader as mentor (role card) for the year.', 'لكل مشارك مرشد من كبار القادة (بطاقة دور) طوال العام.', 10),
('flc-2026', 'FL-2026', 2026, 'running', 12, '2026-09-01', '2027-06-30', 'Future Leaders cohort 2026', 'دفعة قادة المستقبل 2026', '[{"id":"flm-safety","title_en":"Leading safety culture","title_ar":"قيادة ثقافة السلامة","format_en":"Three days with a site visit","format_ar":"ثلاثة أيام مع زيارة ميدانية","weeks":6,"competency_ids":["fl-safety-leadership"]},{"id":"flm-regulation","title_en":"Regulation, licensing and international standards","title_ar":"التنظيم والترخيص والمعايير الدولية","format_en":"Three days with the licensing team","format_ar":"ثلاثة أيام مع فريق الترخيص","weeks":6,"competency_ids":["fl-regulatory"]},{"id":"flm-project","title_en":"Project, cost and outage economics","title_ar":"المشاريع والتكاليف واقتصاديات الانقطاعات","format_en":"Three days with a case study","format_ar":"ثلاثة أيام مع دراسة حالة","weeks":6,"competency_ids":["fl-project-cost"]},{"id":"flm-stakeholder","title_en":"Stakeholders, public communication and international affairs","title_ar":"أصحاب المصلحة والتواصل العام والشؤون الدولية","format_en":"Three days with a media exercise","format_ar":"ثلاثة أيام مع تمرين إعلامي","weeks":6,"competency_ids":["fl-stakeholder"]},{"id":"flm-knowledge","title_en":"Knowledge management and succession","title_ar":"إدارة المعرفة والتعاقب","format_en":"Three days with a capture interview","format_ar":"ثلاثة أيام مع مقابلة توثيق","weeks":6,"competency_ids":["fl-knowledge"]},{"id":"flm-future","title_en":"Leading the future plant: digital change, AI-augmented teams and new reactors","title_ar":"قيادة محطة المستقبل: التحول الرقمي والفرق المعززة بالذكاء الاصطناعي والمفاعلات الجديدة","format_en":"Three days with a governed AI drill and the 360 (form 2)","format_ar":"ثلاثة أيام مع تمرين ذكاء اصطناعي منضبط وتقييم 360 (النموذج 2)","weeks":6,"competency_ids":["fl-safety-leadership","fl-regulatory"]}]'::jsonb, 'Each participant writes a short policy paper on a question an executive sponsors (for example, how a future fleet would change workforce planning). Concept work: no deployment decision implied.', 'يكتب كل مشارك ورقة سياسات قصيرة حول سؤال يرعاه أحد التنفيذيين (مثل كيف سيغيّر أسطول مستقبلي تخطيط القوى العاملة). عمل مفاهيمي: لا يُفهم منه أي قرار نشر.', 'Each participant has a senior leader as mentor (role card) for the year.', 'لكل مشارك مرشد من كبار القادة (بطاقة دور) طوال العام.', 20),
('flc-2027', 'FL-2027', 2027, 'open', 12, '2027-09-01', '2028-06-30', 'Future Leaders cohort 2027 (nominations open)', 'دفعة قادة المستقبل 2027 (الترشيحات مفتوحة)', '[{"id":"flm-safety","title_en":"Leading safety culture","title_ar":"قيادة ثقافة السلامة","format_en":"Three days with a site visit","format_ar":"ثلاثة أيام مع زيارة ميدانية","weeks":6,"competency_ids":["fl-safety-leadership"]},{"id":"flm-regulation","title_en":"Regulation, licensing and international standards","title_ar":"التنظيم والترخيص والمعايير الدولية","format_en":"Three days with the licensing team","format_ar":"ثلاثة أيام مع فريق الترخيص","weeks":6,"competency_ids":["fl-regulatory"]},{"id":"flm-project","title_en":"Project, cost and outage economics","title_ar":"المشاريع والتكاليف واقتصاديات الانقطاعات","format_en":"Three days with a case study","format_ar":"ثلاثة أيام مع دراسة حالة","weeks":6,"competency_ids":["fl-project-cost"]},{"id":"flm-stakeholder","title_en":"Stakeholders, public communication and international affairs","title_ar":"أصحاب المصلحة والتواصل العام والشؤون الدولية","format_en":"Three days with a media exercise","format_ar":"ثلاثة أيام مع تمرين إعلامي","weeks":6,"competency_ids":["fl-stakeholder"]},{"id":"flm-knowledge","title_en":"Knowledge management and succession","title_ar":"إدارة المعرفة والتعاقب","format_en":"Three days with a capture interview","format_ar":"ثلاثة أيام مع مقابلة توثيق","weeks":6,"competency_ids":["fl-knowledge"]},{"id":"flm-future","title_en":"Leading the future plant: digital change, AI-augmented teams and new reactors","title_ar":"قيادة محطة المستقبل: التحول الرقمي والفرق المعززة بالذكاء الاصطناعي والمفاعلات الجديدة","format_en":"Three days with a governed AI drill and the 360 (form 2)","format_ar":"ثلاثة أيام مع تمرين ذكاء اصطناعي منضبط وتقييم 360 (النموذج 2)","weeks":6,"competency_ids":["fl-safety-leadership","fl-regulatory"]}]'::jsonb, 'Each participant writes a short policy paper on a question an executive sponsors (for example, how a future fleet would change workforce planning). Concept work: no deployment decision implied.', 'يكتب كل مشارك ورقة سياسات قصيرة حول سؤال يرعاه أحد التنفيذيين (مثل كيف سيغيّر أسطول مستقبلي تخطيط القوى العاملة). عمل مفاهيمي: لا يُفهم منه أي قرار نشر.', 'Each participant has a senior leader as mentor (role card) for the year.', 'لكل مشارك مرشد من كبار القادة (بطاقة دور) طوال العام.', 30)
insert into kafaa_fl_competencies (id, code, sort, title_en, title_ar, summary_en, summary_ar, area_en, area_ar, descriptors, skill_targets, route, external_ids, sources) values
('fl-safety-leadership', 'FL-1', 10, 'Safety culture leadership', 'قيادة ثقافة السلامة', 'Leads so that nuclear safety is the overriding priority in decisions, resources and behaviours across an organisation, not only a team.', 'يقود بحيث تكون السلامة النووية الأولوية العليا في القرارات والموارد والسلوكيات على مستوى المؤسسة لا الفريق فقط.', 'Safety and safety culture', 'السلامة وثقافة السلامة', '{"1":{"en":"Explains the safety-culture traits and how leaders influence them.","ar":"يشرح سمات ثقافة السلامة وكيف يؤثر القادة فيها."},"2":{"en":"Uses safety-culture observations and operating experience to set priorities in their own area.","ar":"يستخدم ملاحظات ثقافة السلامة والخبرة التشغيلية لتحديد الأولويات في نطاقه."},"3":{"en":"Balances production, cost and safety openly across functions and makes the trade-offs visible.","ar":"يوازن علناً بين الإنتاج والتكلفة والسلامة عبر الوظائف ويُظهر المفاضلات."},"4":{"en":"Shapes organisation-wide safety-culture improvement and answers to oversight for it.","ar":"يشكّل تحسين ثقافة السلامة على مستوى المؤسسة ويُسأل عنه أمام جهات الإشراف."}}'::jsonb, '{"sk-sc-02":3,"sk-ld-02":3,"sk-sc-01":3}'::jsonb, '[{"kind":"module","ref":"flm-safety","title_en":"Module 1: Leading safety culture","title_ar":"الوحدة 1: قيادة ثقافة السلامة"},{"kind":"programme","ref":"prog-cld","title_en":"Culture of leadership development (academy)","title_ar":"تطوير ثقافة القيادة (الأكاديمية)"},{"kind":"route","ref":"/safety-culture","title_en":"Safety culture traits","title_ar":"سمات ثقافة السلامة"},{"kind":"external","ref":"fx-iaea-nem","title_en":"IAEA School of Nuclear Energy Management","title_ar":"مدرسة إدارة الطاقة النووية التابعة للوكالة"}]'::jsonb, array['fx-iaea-nem']::text[], '[{"label":"IAEA · International Nuclear Management Academy (INMA)","url":"https://www.iaea.org/node/17745","as_of":"2026-10-10","precision":"secondary"}]'::jsonb),
('fl-regulatory', 'FL-2', 20, 'Regulatory affairs literacy', 'الإلمام بالشؤون التنظيمية', 'Understands how the regulator, the licensing basis and international safety standards shape decisions, and works with them early and openly. This is literacy, not a regulatory role.', 'يفهم كيف يشكّل المنظِّم وأساس الترخيص ومعايير السلامة الدولية القرارات، ويتعامل معها مبكراً وبشفافية. هذا إلمام وليس دوراً تنظيمياً.', 'Regulation and licensing', 'التنظيم والترخيص', '{"1":{"en":"Explains, at a high level, the role of the national regulator, licence conditions and the IAEA safety standards.","ar":"يشرح على مستوى عام دور المنظِّم الوطني وشروط الترخيص ومعايير السلامة للوكالة الدولية للطاقة الذرية."},"2":{"en":"Uses the licensing basis and technical specifications correctly when planning work in their area.","ar":"يستخدم أساس الترخيص والمواصفات الفنية بشكل صحيح عند تخطيط العمل في نطاقه."},"3":{"en":"Prepares a change or submission with the licensing team and anticipates the questions it will raise.","ar":"يُعدّ تغييراً أو تقديماً مع فريق الترخيص ويتوقع الأسئلة التي سيثيرها."},"4":{"en":"Leads engagement on new technology, such as SMRs, where the path is still being defined. No deployment decision implied.","ar":"يقود التواصل بشأن التقنيات الجديدة، مثل المفاعلات الصغيرة، حيث ما زال المسار قيد التحديد. لا يُفهم من ذلك أي قرار نشر."}}'::jsonb, '{"sk-ns-02":2,"sk-ns-02-licensing":2,"sk-fs-adv-regulation":1}'::jsonb, '[{"kind":"module","ref":"flm-regulation","title_en":"Module 2: Regulation, licensing and international standards","title_ar":"الوحدة 2: التنظيم والترخيص والمعايير الدولية"},{"kind":"route","ref":"/skills/sk-ns-02-licensing","title_en":"Skill: licensing basis and regulatory submissions","title_ar":"مهارة: أساس الترخيص والتقديمات التنظيمية"},{"kind":"external","ref":"fx-inma","title_en":"INMA-endorsed master''s programmes","title_ar":"برامج الماجستير المعتمدة من INMA"}]'::jsonb, array['fx-inma','fx-nea-nextgen']::text[], '[{"label":"IAEA · International Nuclear Management Academy (INMA)","url":"https://www.iaea.org/node/17745","as_of":"2026-10-10","precision":"secondary"}]'::jsonb),
('fl-project-cost', 'FL-3', 30, 'Project and cost control', 'ضبط المشاريع والتكاليف', 'Plans, estimates and controls projects and outages against scope, schedule, cost and risk, with safety and quality as fixed constraints.', 'يخطط المشاريع والانقطاعات ويقدّرها ويضبطها وفق النطاق والجدول والتكلفة والمخاطر، مع بقاء السلامة والجودة قيوداً ثابتة.', 'Projects, cost and economics', 'المشاريع والتكاليف والاقتصاد', '{"1":{"en":"Reads a project schedule and budget and explains a variance.","ar":"يقرأ جدول المشروع وميزانيته ويشرح أي انحراف."},"2":{"en":"Builds and tracks a work plan with milestones, costs and risks for a small project.","ar":"يبني خطة عمل لمشروع صغير بمعالمها وتكاليفها ومخاطرها ويتابعها."},"3":{"en":"Leads a multi-discipline project or outage scope with earned-value or equivalent controls.","ar":"يقود مشروعاً متعدد التخصصات أو نطاق انقطاع بضوابط القيمة المكتسبة أو ما يعادلها."},"4":{"en":"Owns a portfolio, sets investment priorities and challenges business cases.","ar":"يملك محفظة مشاريع ويحدد أولويات الاستثمار ويتحدى دراسات الجدوى."}}'::jsonb, '{"sk-en-01-project":2,"sk-mp-01-outage":2,"sk-fs-tr-analytical":2}'::jsonb, '[{"kind":"module","ref":"flm-project","title_en":"Module 3: Project, cost and outage economics","title_ar":"الوحدة 3: المشاريع والتكاليف واقتصاديات الانقطاعات"},{"kind":"programme","ref":"prog-one","title_en":"ONE leadership programme (academy)","title_ar":"برنامج ONE القيادي (الأكاديمية)"},{"kind":"route","ref":"/opportunities/future","title_en":"Practise on a future-skills gig","title_ar":"تدرّب عبر مهمة مهارات مستقبلية"}]'::jsonb, array['fx-enen2plus']::text[], '[{"label":"IAEA · International Nuclear Management Academy (INMA)","url":"https://www.iaea.org/node/17745","as_of":"2026-10-10","precision":"secondary"}]'::jsonb),
('fl-stakeholder', 'FL-4', 40, 'Stakeholder and international affairs', 'شؤون أصحاب المصلحة والشؤون الدولية', 'Represents the organisation credibly with communities, partners and international bodies, and explains nuclear energy in plain language.', 'يمثّل المؤسسة بمصداقية أمام المجتمعات والشركاء والهيئات الدولية، ويشرح الطاقة النووية بلغة واضحة.', 'Stakeholders and international affairs', 'أصحاب المصلحة والشؤون الدولية', '{"1":{"en":"Explains the organisation''s role and the basics of nuclear energy to a non-specialist.","ar":"يشرح دور المؤسسة وأساسيات الطاقة النووية لغير المتخصصين."},"2":{"en":"Works effectively with partner organisations and suppliers from other cultures.","ar":"يعمل بفعالية مع الشركاء والموردين من ثقافات أخرى."},"3":{"en":"Represents the organisation in external forums and handles difficult questions calmly.","ar":"يمثّل المؤسسة في المحافل الخارجية ويتعامل مع الأسئلة الصعبة بهدوء."},"4":{"en":"Builds long-term partnerships and contributes to international programmes.","ar":"يبني شراكات طويلة الأمد ويسهم في البرامج الدولية."}}'::jsonb, '{"sk-fs-tr-crosscultural":2,"sk-fs-tr-leadership":2,"sk-fs-tr-empathy":2}'::jsonb, '[{"kind":"module","ref":"flm-stakeholder","title_en":"Module 4: Stakeholders, public communication and international affairs","title_ar":"الوحدة 4: أصحاب المصلحة والتواصل العام والشؤون الدولية"},{"kind":"external","ref":"fx-nea-nextgen","title_en":"NEA NextGen Nuclear Leaders Summer School","title_ar":"المدرسة الصيفية لقادة الجيل القادم النوويين (NEA)"},{"kind":"route","ref":"/communities","title_en":"Communities of practice","title_ar":"مجتمعات الممارسة"}]'::jsonb, array['fx-nea-nextgen','fx-kings']::text[], '[{"label":"OECD-NEA · NextGen Nuclear Leaders Summer School 2026, final programme (PDF)","url":"https://oecd-nea.org/upload/docs/application/pdf/2026-07/nextgen_nuclear_leaders_summer_school_2026_final_programme.pdf","as_of":"2026-10-10","precision":"secondary"}]'::jsonb),
('fl-knowledge', 'FL-5', 50, 'Knowledge management', 'إدارة المعرفة', 'Treats nuclear knowledge as an asset: finds what is critical, makes sure it is captured and passed on, and plans for succession.', 'يتعامل مع المعرفة النووية كأصل: يحدد ما هو حرج ويضمن توثيقه ونقله ويخطط للتعاقب.', 'Knowledge management', 'إدارة المعرفة', '{"1":{"en":"Explains why knowledge loss is a safety and business risk.","ar":"يشرح لماذا يمثّل فقدان المعرفة خطراً على السلامة والأعمال."},"2":{"en":"Captures and shares their own critical knowledge with approved methods.","ar":"يوثّق معرفته الحرجة ويشاركها بالطرق المعتمدة."},"3":{"en":"Runs knowledge-loss assessments and capture plans for a team.","ar":"يجري تقييمات فقدان المعرفة وخطط التوثيق لفريق."},"4":{"en":"Sets knowledge strategy and succession for a function.","ar":"يضع استراتيجية المعرفة والتعاقب لوظيفة كاملة."}}'::jsonb, '{"sk-ld-01-coach":3,"sk-fs-tr-curiosity":2,"sk-ld-01-instruct":2}'::jsonb, '[{"kind":"module","ref":"flm-knowledge","title_en":"Module 5: Knowledge management and succession","title_ar":"الوحدة 5: إدارة المعرفة والتعاقب"},{"kind":"route","ref":"/knowledge/capture","title_en":"Knowledge capture studio","title_ar":"استوديو توثيق المعرفة"},{"kind":"route","ref":"/knowledge","title_en":"Knowledge library","title_ar":"مكتبة المعرفة"}]'::jsonb, array['fx-iaea-nem']::text[], '[{"label":"IAEA · International Nuclear Management Academy (INMA)","url":"https://www.iaea.org/node/17745","as_of":"2026-10-10","precision":"secondary"}]'::jsonb)
insert into kafaa_fl_external (id, kind, sort, owner_en, owner_ar, title_en, title_ar, summary_en, summary_ar, dates_en, dates_ar, year_from, year_to, competency_ids, sources) values
('fx-nea-nextgen', 'summer_school', 10, 'OECD Nuclear Energy Agency (NEA)', 'وكالة الطاقة النووية التابعة لمنظمة التعاون الاقتصادي والتنمية', 'NextGen Nuclear Leaders Summer School', 'المدرسة الصيفية لقادة الجيل القادم النوويين', 'The NEA''s flagship summer school for the next generation of nuclear leaders, convened through its Global Forum on Nuclear Education, Science, Technology and Policy.', 'المدرسة الصيفية الرئيسية للوكالة لقادة الجيل القادم، تُعقد عبر منتداها العالمي للتعليم والعلوم والتكنولوجيا والسياسات النووية.', '2026 programme published', 'نُشر برنامج 2026', 2026, 2026, array['fl-stakeholder','fl-regulatory']::text[], '[{"label":"OECD-NEA · NextGen Nuclear Leaders Summer School 2026, final programme (PDF)","url":"https://oecd-nea.org/upload/docs/application/pdf/2026-07/nextgen_nuclear_leaders_summer_school_2026_final_programme.pdf","as_of":"2026-10-10","precision":"secondary"}]'::jsonb),
('fx-iaea-nem', 'school', 20, 'International Atomic Energy Agency (IAEA)', 'الوكالة الدولية للطاقة الذرية', 'IAEA School of Nuclear Energy Management', 'مدرسة إدارة الطاقة النووية التابعة للوكالة الدولية للطاقة الذرية', 'For young professionals in Member States planning or starting nuclear power programmes; the Japan-hosted Nuclear Energy Management programme serves as a practicum component of INMA.', 'للمهنيين الشباب في الدول الأعضاء التي تخطط لبرامج القوى النووية أو تبدأها؛ ويُعد برنامج إدارة الطاقة النووية الذي تستضيفه اليابان مكوّناً تطبيقياً ضمن أكاديمية INMA.', 'Recurring school (see the source for current dates)', 'مدرسة دورية (راجع المصدر للمواعيد الحالية)', null, null, array['fl-safety-leadership','fl-knowledge']::text[], '[{"label":"IAEA · International Nuclear Management Academy (INMA)","url":"https://www.iaea.org/node/17745","as_of":"2026-10-10","precision":"secondary"}]'::jsonb),
('fx-inma', 'masters', 30, 'IAEA International Nuclear Management Academy (INMA)', 'الأكاديمية الدولية للإدارة النووية (INMA) التابعة للوكالة', 'INMA-endorsed master''s programmes in nuclear technology management', 'برامج ماجستير إدارة التكنولوجيا النووية المعتمدة من INMA', 'INMA endorses university master''s programmes in nuclear technology management against an IAEA competency model; about 10 universities are reported, and Sofia University was endorsed in early 2025.', 'تعتمد INMA برامج ماجستير جامعية في إدارة التكنولوجيا النووية وفق نموذج كفاءات للوكالة؛ ويُذكر نحو 10 جامعات، واعتُمدت جامعة صوفيا مطلع 2025.', 'Endorsements continue; Sofia University endorsed early 2025', 'الاعتمادات مستمرة؛ اعتُمدت جامعة صوفيا مطلع 2025', 2025, null, array['fl-regulatory','fl-project-cost','fl-knowledge']::text[], '[{"label":"IAEA · International Nuclear Management Academy (INMA)","url":"https://www.iaea.org/node/17745","as_of":"2026-10-10","precision":"secondary"},{"label":"Sofia University · INMA endorsement (early 2025)","url":"https://phys.uni-sofia.bg/?p=28612","as_of":"2026-10-10","precision":"secondary"},{"label":"MEPhI · nuclear technology management graduates","url":"https://eng.mephi.ru/news/120165","as_of":"2026-10-10","precision":"secondary"}]'::jsonb),
('fx-cnnems', 'school', 40, 'University of Saskatchewan (IAEA-led)', 'جامعة ساسكاتشوان (بقيادة الوكالة)', 'Canadian National Nuclear Energy Management School', 'المدرسة الوطنية الكندية لإدارة الطاقة النووية', 'An IAEA-led nuclear energy management school hosted by the University of Saskatchewan.', 'مدرسة لإدارة الطاقة النووية بقيادة الوكالة تستضيفها جامعة ساسكاتشوان.', 'Reported November 2025', 'وردت في نوفمبر 2025', 2025, null, array['fl-safety-leadership','fl-project-cost']::text[], '[{"label":"ANS Nuclear Newswire · Education and training to support the Canadian nuclear workforce (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10","precision":"secondary"}]'::jsonb),
('fx-enen2plus', 'mobility', 50, 'European Nuclear Education Network (ENEN)', 'الشبكة الأوروبية للتعليم النووي (ENEN)', 'ENEN2plus mobility grants', 'منح التنقل ENEN2plus', 'Lump-sum grants paid to the learner for internships, on-the-job training, exchanges, conferences and courses; open to students and early-career professionals with up to 10 years'' experience, with deadlines every 2 months.', 'منح مقطوعة تُدفع للمتعلم لقاء التدريب الداخلي والتدريب أثناء العمل والتبادل والمؤتمرات والدورات؛ متاحة للطلاب والمهنيين في بداية مسيرتهم بخبرة حتى 10 سنوات، ومواعيد التقديم كل شهرين.', 'June 2022 to May 2026 (CORDIS 101061677)', 'من يونيو 2022 إلى مايو 2026 (CORDIS 101061677)', 2022, 2026, array['fl-project-cost','fl-stakeholder']::text[], '[{"label":"CORDIS · ENEN2plus project 101061677","url":"https://cordis.europa.eu/project/id/101061677","as_of":"2026-10-10","precision":"secondary"}]'::jsonb),
('fx-nntp', 'trainee', 60, 'Fortum, TVO, Uniper and Vattenfall', 'فورتوم وTVO ويونيبر وفاتنفال', 'Nordic Nuclear Trainee Programme', 'برنامج المتدربين النوويين الشمالي', 'A trainee programme run jointly by four operators: six in-person modules of three days with site visits, a project assignment and mentoring. Its module, project and mentor triad is the pattern for this track.', 'برنامج متدربين يديره أربعة مشغّلين معاً: ست وحدات حضورية مدة كل منها ثلاثة أيام مع زيارات ميدانية ومشروع وإرشاد. وثلاثية الوحدة والمشروع والمرشد هي نمط هذا المسار.', 'Launched 2019; fourth round January to December 2027', 'أُطلق في 2019؛ الجولة الرابعة من يناير إلى ديسمبر 2027', 2019, 2027, array['fl-safety-leadership','fl-knowledge']::text[], '[{"label":"Fortum · Nordic Nuclear Trainee Programme","url":"https://www.fortum.com/careers/NNTP","as_of":"2026-10-10","precision":"secondary"}]'::jsonb),
('fx-kings', 'internship', 70, 'KEPCO International Nuclear Graduate School (KINGS)', 'كلية كيبكو الدولية للدراسات العليا النووية (KINGS)', 'KINGS master''s and the ENEC internship in Korea', 'ماجستير KINGS وبرنامج التدريب الداخلي في كوريا', 'KINGS was established in 2012 with a two-year master''s accredited by Korea''s Ministry of Education; ENEC''s internship with KINGS ran a second edition from 2016 with a first batch of 10 Emirati students.', 'تأسست KINGS في 2012 ببرنامج ماجستير لمدة عامين معتمد من وزارة التعليم الكورية؛ ونُظمت النسخة الثانية من برنامج التدريب الداخلي مع KINGS منذ 2016 بدفعة أولى من 10 طلاب إماراتيين.', 'Established 2012; internship edition from 2016 (historical)', 'تأسست 2012؛ نسخة التدريب منذ 2016 (تاريخي)', 2012, null, array['fl-stakeholder']::text[], '[{"label":"ENEC · Emirati students participate in ENEC internship program in South Korea","url":"https://www.enec.gov.ae/news/latest-news/emirati-students-participate-in-enec-internship-program-in-south-korea","as_of":"2026-10-10","precision":"secondary"}]'::jsonb)
